arguments.file_text:
@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Manage Shipments</PageTitle>

<h1>Shipments</h1>

<button class="btn btn-success mb-3" @onclick="ShowCreateForm">+ New Shipment</button>

@if (showCreate)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5>Create Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input @bind="newShipment.Origin" class="form-control" placeholder="Origin" />
                </div>
                <div class="col-md-3">
                    <input @bind="newShipment.Destination" class="form-control" placeholder="Destination" />
                </div>
                <div class="col-md-3">
                    <input @bind="newShipment.CustomerEmail" class="form-control" placeholder="Customer Email" />
                </div>
                <div class="col-md-2">
                    <input type="date" @bind="newShipment.EstimatedDelivery" class="form-control" />
                </div>
                <div class="col-md-1">
                    <button class="btn btn-primary" @onclick="CreateShipment">Save</button>
                </div>
            </div>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in shipments)
            {
                <tr>
                    <td><code>@shipment.TrackingNumber</code></td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.EstimatedDelivery.ToString("yyyy-MM-dd")</td>
                    <td>
                        <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                value="@shipment.Status"
                                @onchange="(e) => UpdateStatus(shipment.Id, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? shipments;
    private Shipment newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
    private bool showCreate;

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ShowCreateForm() => showCreate = !showCreate;

    private async Task CreateShipment()
    {
        await ShipmentService.CreateShipmentAsync(newShipment);
        newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
        showCreate = false;
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, status);
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
